-- Seed: Recycling & Waste Management for SMEs in Ontario — 4 content modules + final quiz
-- Idempotent: safe to re-run. Uses fixed UUIDs.

DO $$
DECLARE
  v_course_id UUID := 'd4e5f6a7-b8c9-0123-defa-345678901234';
  v_mod_ids UUID[] := ARRAY[
    'd4e50001-0000-0000-0000-000000000001',
    'd4e50001-0000-0000-0000-000000000002',
    'd4e50001-0000-0000-0000-000000000003',
    'd4e50001-0000-0000-0000-000000000004',
    'd4e50001-0000-0000-0000-000000000005'
  ]::UUID[];
BEGIN
  -- Course
  INSERT INTO public.courses (id, title, description, short_description, duration_minutes, is_published)
  VALUES (
    v_course_id,
    'Recycling & Waste Management for SMEs in Ontario',
    'A 4-module training program built for Ontario small and medium-sized enterprises — business owners, managers, and frontline staff. Built on official RPRA guidance and Ontario MOE rules, this course covers Ontario''s waste challenge, the recycling streams every SME should run, the new Extended Producer Responsibility (EPR) framework, and a step-by-step waste-station setup any SME can complete in one afternoon.',
    'Practical recycling and waste-management training for Ontario SMEs — EPR rules, waste streams, contamination, and a 5-step setup plan.',
    105,
    true
  )
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    description = EXCLUDED.description,
    short_description = EXCLUDED.short_description,
    duration_minutes = EXCLUDED.duration_minutes,
    is_published = EXCLUDED.is_published,
    updated_at = now();

  -- Clear existing modules for clean re-seed
  DELETE FROM public.modules WHERE course_id = v_course_id;

  -- Modules
  INSERT INTO public.modules (id, course_id, title, description, content, order_index, duration_minutes, has_quiz, quiz_pass_mark) VALUES
  (v_mod_ids[1], v_course_id, 'Waste Generation in Ontario',
   'Ontario''s waste challenge, the recycling vs. landfill reality, and the role SMEs play in it.',
   E'<h2>Overview of Waste Generation in Ontario</h2><p>Ontario generates more than <strong>12 million tonnes</strong> of municipal solid waste every year. That''s roughly one tonne per person — among the highest waste generation rates in Canada. Despite decades of recycling programs, <strong>only about one-third</strong> of that waste is diverted from landfill. The rest ends up buried in the ground.</p><p>Small and medium-sized businesses are a significant part of that picture. SMEs across Ontario''s <strong>commercial, industrial, and institutional (IC&I) sectors</strong> generate millions of tonnes of waste annually — much of which could be recycled or composted, but isn''t.</p><h3>Key Numbers</h3><ul><li><strong>12M+ tonnes</strong> of municipal waste generated in Ontario every year</li><li><strong>~33%</strong> diverted from landfill — one-third recycled or composted</li><li><strong>50%+</strong> of IC&I waste is estimated to be recyclable but landfilled</li><li><strong>$Millions</strong> annual cost of contaminated recycling loads in Ontario</li></ul><h3>The Recycling vs. Landfill Reality</h3><p>Most Ontarians assume that what goes in the recycling bin gets recycled. The reality is more complicated. When recyclable materials are <strong>contaminated</strong> — mixed with food waste, placed in plastic bags, or simply the wrong item — they often cannot be processed. They end up in landfill anyway.</p><p>Ontario''s landfill space is finite. Several major landfill sites in southern Ontario are approaching capacity. When landfills fill up, new ones must be built — at enormous cost and with significant community opposition. Every tonne diverted from landfill extends the life of existing sites and avoids those costs.</p><h3>Do''s and Don''ts</h3><ul><li>✓ Rinse containers before placing in recycling — ✗ Don''t leave food residue in containers</li><li>✓ Separate materials into the correct streams — ✗ Don''t mix paper, plastics, and organics</li><li>✓ Use clearly labelled waste stations — ✗ Don''t rely on staff to "figure it out"</li><li>✓ Flatten cardboard before collection — ✗ Don''t put large boxes in recycling unsquished</li><li>✓ Book hazardous waste collection in advance — ✗ Don''t pour chemicals down the drain</li></ul><h3>System Capacity and Cost Pressures</h3><p>Ontario''s <strong>Material Recovery Facilities (MRFs)</strong> — the sorting plants that process blue bin material — operate at or near capacity in many regions. When contamination rates are high, more material must be rejected and sent to landfill. This drives up costs for municipalities, and increasingly those costs are being shifted to producers and businesses.</p><ul><li>High contamination = more landfill = higher system costs for everyone</li><li>Clean, well-sorted recyclables have <strong>real commercial value</strong> — they are sold as raw materials</li><li>Ontario is transitioning to a system where producers and businesses pay more of the recycling bill</li></ul><h3>Real-World Example — Toronto Restaurant</h3><p>A Toronto restaurant generates 2 tonnes of waste per week. If 60% is organic food waste and recyclable packaging mixed together, <strong>none of it can be recycled</strong> — it all goes to landfill. Separating those materials costs the restaurant nothing extra but would divert over 1 tonne per week from landfill and may reduce disposal fees.</p><h3>The Role of SMEs in Waste Generation</h3><p>Ontario''s <strong>IC&I sector — which includes all SMEs — generates approximately 40%</strong> of total provincial waste. Unlike households, which are served by municipal collection, most SMEs are responsible for arranging and paying for their own waste removal and recycling services.</p><p>This means SMEs have both <strong>more control and more responsibility</strong>. A business that sorts correctly saves money on disposal costs, reduces its environmental footprint, and in some cases generates revenue from materials with value.</p><h3>Typical Waste Streams by SME Type</h3><ul><li><strong>Office / professional services</strong> — Paper, cardboard, electronics, food waste, plastic packaging</li><li><strong>Restaurant / café</strong> — Organic food waste, glass, cardboard, cooking oil, packaging</li><li><strong>Retail store</strong> — Cardboard, plastic wrap, product packaging, food waste (grocery)</li><li><strong>Warehouse / distribution</strong> — Cardboard, stretch wrap, pallets, plastic strapping, foam</li><li><strong>Light manufacturing</strong> — Metals, cardboard, plastics, chemical waste, wood pallets</li></ul><h3>Instructor Note</h3><p>Waste often contains <strong>value</strong> — recyclable cardboard, metals, and some plastics have a market price. The goal is not just compliance, it''s also good business sense. Ask yourself: <strong>How much does your business spend on waste disposal each month?</strong> Most SME owners don''t know — and that''s an opportunity.</p>',
   1, 15, true, 70),

  (v_mod_ids[2], v_course_id, 'Recycling Basics for SMEs',
   'The four core waste streams, contamination, and the common SME recycling mistakes.',
   E'<h2>What Recycling Actually Means</h2><p>Recycling is the process of collecting used materials, sorting them by type, processing them into raw materials, and using those raw materials to manufacture new products. It is <strong>not</strong> simply putting something in a blue bin — that is just the first step.</p><p>For recycling to work, the materials collected must be:</p><ul><li>The <strong>right type</strong> (accepted in the recycling stream for that region)</li><li><strong>Clean enough</strong> (free from food contamination and other residues)</li><li><strong>Not mixed incorrectly</strong> with other materials that spoil the batch</li></ul><p>When these conditions are met, recovered materials have genuine commercial value. Aluminum, clean cardboard, and certain plastics are bought and sold on commodity markets. When conditions are not met, the material is rejected and sent to landfill.</p><h3>Clean vs. Contaminated Materials</h3><p>Contamination is the biggest problem in Ontario''s recycling system — and one of the most preventable. It occurs when the wrong item enters the wrong bin, or when the right item is in the right bin but is too dirty to be processed.</p><ul><li><strong>Paper & Cardboard</strong> — ✓ Clean, dry, unsoiled paper and cardboard. ✗ Greasy pizza boxes, wet cardboard, tissues, food-soiled paper.</li><li><strong>Plastics</strong> — ✓ Rinsed #1 PET and #2 HDPE bottles and containers. ✗ Plastic bags, black plastic, Styrofoam, unrinsed food containers.</li><li><strong>Metals</strong> — ✓ Rinsed aluminum cans, steel food tins, clean foil. ✗ Batteries, scrap metal, paint tins with wet paint.</li><li><strong>Glass</strong> — ✓ Rinsed glass bottles and jars. ✗ Broken glassware, ceramics, lightbulbs, window glass.</li><li><strong>Organics / Food</strong> — ✓ Raw and cooked food scraps, coffee, paper napkins. ✗ Plastic bags mixed with food, non-food items, liquids in large quantities.</li></ul><h2>Core Recycling Streams for SMEs</h2><p>Most Ontario SMEs should maintain <strong>at minimum four distinct waste streams</strong>. Depending on business type, additional streams (cooking oil, hazardous materials, electronics) may be needed.</p><h3>Stream 1: Recycling (Blue Bin)</h3><ul><li>Paper, cardboard (flattened), newspapers, office paper, envelopes, magazines</li><li>Plastic bottles and containers (#1 PET and #2 HDPE) — rinsed</li><li>Metal cans and tins — rinsed; clean aluminum foil</li><li>Glass bottles and jars — rinsed</li><li>Milk cartons and juice tetra-paks — rinsed</li></ul><p><strong>Never</strong> place plastic bags in the blue bin. They jam sorting machinery. Collect separately and take to grocery store drop-off bins.</p><h3>Stream 2: Organics / Food Waste (Green Bin)</h3><ul><li>All food scraps — raw and cooked, including meat, fish, and dairy</li><li>Coffee grounds and paper filters; tea bags (paper only)</li><li>Paper napkins, paper towels, soiled paper plates</li><li>Soiled cardboard food packaging (e.g., greasy pizza boxes — bottom portion)</li></ul><h3>Stream 3: Landfill / Garbage (Grey/Black Bin)</h3><ul><li>Styrofoam and foam packaging</li><li>Black plastic containers (cannot be sorted by NIR scanners)</li><li>Chip bags, candy wrappers, multi-layer film packaging</li><li>Tissues, diapers, hygiene products</li><li>Broken ceramics, dishes, window glass</li></ul><h3>Stream 4: Special Drop-Off / Regulated Materials</h3><ul><li><strong>Batteries</strong> — all types; Canadian Tire, Home Depot, municipal depot</li><li><strong>Electronics</strong> — computers, phones, printers; registered electronics drop-off</li><li><strong>Cooking oil</strong> — collected by licensed grease recyclers (many offer free collection)</li><li><strong>Fluorescent bulbs and CFLs</strong> — contain mercury; Home Depot, IKEA</li><li><strong>Chemicals, solvents, paints</strong> — Household/Business Hazardous Waste depots</li></ul><h2>Common SME Recycling Mistakes</h2><ul><li><strong>Wishful recycling</strong> — Putting items in recycling "just in case." If unsure, check RPRA''s Where to Recycle tool — or put it in garbage rather than contaminate a whole bin.</li><li><strong>Bagging recyclables</strong> — A plastic bag of clean recyclables placed in the blue bin is treated as garbage at the sorting facility. The bag is not opened.</li><li><strong>Skipping the rinse</strong> — A small amount of food residue can ruin an entire bale of recyclable paper worth thousands of dollars.</li><li><strong>Ignoring cardboard size</strong> — Flatten all boxes. Large boxes should be broken down to fit collection containers.</li><li><strong>Mixing hazardous waste</strong> — Batteries, chemicals, or fluorescent bulbs in the general bin cause fires, contamination, and equipment damage.</li><li><strong>No staff training</strong> — A five-minute briefing and clear bin labels prevent most contamination issues.</li></ul><h2>Practical SME Scenarios</h2><h3>Office / Professional Services</h3><p>A 20-person legal office generates mostly paper waste, coffee cups, and lunch packaging. Key actions: paper recycling bin at every desk, organics bin in the kitchen for coffee grounds and food scraps, a cardboard flat-pack area near the printer, and a labelled general waste bin for chip bags and cling wrap.</p><h3>Restaurant / Café</h3><p>A 30-seat restaurant generates large volumes of organic food waste, cooking oil, glass bottles, and cardboard from deliveries. Key actions: a large organics bin in the kitchen with daily collection, an oil collection arrangement with a licensed grease recycler (often free), glass bottle collection by bin type, and flattened cardboard stacked near the back door.</p><h3>Warehouse / Distribution</h3><p>A mid-sized distribution centre generates large quantities of cardboard, plastic stretch wrap, and foam packaging. Key actions: a cardboard compactor or <strong>baler</strong> if volume is sufficient (compacted cardboard is sold for profit), a stretch wrap collection point, and foam take-back with the original supplier if possible.</p>',
   2, 15, true, 70),

  (v_mod_ids[3], v_course_id, 'Ontario''s New Recycling Rules — EPR',
   'Why Ontario changed the system, what Extended Producer Responsibility means, and where SMEs fit.',
   E'<h2>Why Ontario Changed the System</h2><p>Ontario''s Blue Box recycling program was run and funded by municipalities for more than 30 years. While it served millions of households, the system had fundamental weaknesses: <strong>inconsistent rules</strong> from city to city, <strong>contamination problems</strong>, and <strong>costs that kept rising</strong> for taxpayers.</p><p>In response, the Ontario government introduced the <strong>Resource Recovery and Circular Economy Act</strong>, which established a new approach called <strong>Extended Producer Responsibility (EPR)</strong>. Under this approach, the businesses that produce or sell products and packaging — <strong>not municipalities or taxpayers</strong> — are financially responsible for what happens to those products when consumers are done with them.</p><p>The new Blue Box program took over from municipalities starting in 2023 and will be <strong>fully producer-operated by January 1, 2026</strong>.</p><h3>Key Message</h3><p>Producers are responsible for recycling costs and outcomes. SMEs influence those outcomes through purchasing decisions and correct sorting behaviour.</p><h2>What Extended Producer Responsibility Means</h2><p>EPR is a policy approach that makes manufacturers and importers responsible for the <strong>end-of-life management</strong> of their products and packaging. In simple terms: if a company puts a plastic bottle, a cardboard box, or a Styrofoam tray into the Ontario market, that company is now <strong>legally required to pay for and manage its recycling</strong>.</p><p>This is enforced by <strong>RPRA</strong> — the Resource Productivity and Recovery Authority — an independent regulatory body that sets targets, collects fees from producers, and ensures the system delivers results.</p><h3>The Six RPRA Programs</h3><ul><li><strong>Blue Box</strong> — Household and SME packaging, paper, and packaging-like products. Paid for by all packaging producers.</li><li><strong>Batteries</strong> — All battery types from single-use to EV batteries. Paid for by battery manufacturers and importers.</li><li><strong>Electronics</strong> — Computers, phones, TVs, and hundreds of other devices. Paid for by electronics producers.</li><li><strong>Lighting</strong> — All bulb types from LED to fluorescent. Paid for by lighting manufacturers.</li><li><strong>Tires</strong> — All vehicle and equipment tires. Paid for by tire producers and importers.</li><li><strong>Household Hazardous Waste</strong> — Paints, chemicals, pesticides, antifreeze, solvents. Paid for by HHW product manufacturers.</li></ul><h2>Who Is Responsible Under EPR?</h2><p>"Producers" under Ontario''s EPR framework are typically:</p><ul><li>Large consumer goods manufacturers (food and beverage companies, consumer product brands)</li><li>Importers who bring products and packaging into Ontario</li><li>Retailers who are the first to sell a product in Ontario (where no other producer is registered)</li></ul><p><strong>Most SMEs are NOT classified as producers</strong> — they are "consumers" who use packaging produced by others. However, the rules are more nuanced for some business types.</p><p>If your SME <strong>imports products</strong> or packaging directly into Ontario, or if you are the <strong>brand owner</strong> on a product with no other registered Ontario producer, you may have producer obligations under RPRA''s programs. Check <strong>rpra.ca</strong> or consult RPRA directly if unsure.</p><h2>Where SMEs Fit in the EPR System</h2><p>Even if your SME is not a registered producer, you play a critical role in EPR''s success:</p><ul><li><strong>Correct sorting reduces costs</strong> — Less contamination = less material rejected = lower system costs that producers pass back through product pricing.</li><li><strong>Buying power signals demand</strong> — When SMEs choose recyclable packaging, you signal market demand to producers — encouraging more sustainable packaging design.</li><li><strong>Waste volumes affect service costs</strong> — The volume and quality of waste your business generates affects collection service costs. Better sorting = lower disposal bills.</li><li><strong>Staff influence outcomes</strong> — Employees make hundreds of sorting decisions every day. Training them is the most direct way to improve performance.</li><li><strong>Drop-off programs save money</strong> — Batteries, electronics, and cooking oil have free registered drop-off programs — saving money vs. commercial disposal.</li></ul><h2>The Blue Box 2026 Transition — What SMEs Should Know</h2><p>From <strong>January 1, 2026</strong>, Ontario''s Blue Box program is operated 100% by producers — with <strong>consistent rules across all Ontario municipalities</strong>.</p><ul><li><strong>Harmonised accepted materials</strong> — The same items will be accepted across all Ontario communities, eliminating the confusion of different local rules</li><li><strong>Expanded scope</strong> — Broader range of packaging types, including some previously excluded items</li><li><strong>Service continuity</strong> — Most SMEs will continue to use the same collection service providers</li><li><strong>Increased accountability</strong> — RPRA has powers to audit and enforce compliance, with penalties for producers who miss recovery targets</li></ul><h3>Real-World Example — One Set of Rules Province-Wide</h3><p>A small retail business in Hamilton that currently sorts recycling slightly differently than a similar store in London can now follow <strong>one consistent set of rules province-wide</strong>. The packaging from the same product is accepted the same way everywhere in Ontario — simplifying staff training significantly.</p><h3>Instructor Note</h3><p>The key message for SMEs is simple: <strong>producers are paying for the system, but your sorting behaviour determines whether the system succeeds or fails</strong>. Think of it like a restaurant kitchen — the supplier (producer) provides the ingredients, but the kitchen staff (SME employees) determine what gets wasted and what gets used.</p>',
   3, 15, true, 70),

  (v_mod_ids[4], v_course_id, 'Practical Waste Actions for SMEs',
   'A 5-step waste-station setup, staff training basics, materials with commercial value, and hazardous-waste basics.',
   E'<h2>What SMEs Must Do</h2><p>Ontario''s regulations for commercial and IC&I waste depend on your municipality and operation size, but the following actions apply to virtually all Ontario SMEs:</p><ul><li><strong>Separate recyclable material</strong> — Under Ontario Regulation 102/94, IC&I facilities above certain thresholds must source-separate designated recyclable materials.</li><li><strong>Arrange compliant collection</strong> — Use a licensed waste hauler for garbage and recyclables. Contracts should specify source-separated collection where required.</li><li><strong>Keep records if required</strong> — Larger operations (typically above 10 employees or specific waste volumes) may be required to maintain waste-audit records and submit diversion reports.</li><li><strong>Handle hazardous waste properly</strong> — Batteries, chemicals, solvents, and other regulated materials must be stored, labelled, and disposed of per the Ontario Environmental Protection Act.</li><li><strong>Post signage at waste stations</strong> — Clear, visible signage is both a regulatory expectation and a practical necessity.</li></ul><p>Always check with your municipality for local-specific commercial waste bylaws. Requirements vary between Toronto, Ottawa, Hamilton, London, and smaller municipalities.</p><h3>What SMEs Are NOT Required to Do</h3><p>Most Ontario SMEs are <strong>not</strong> required to:</p><ul><li>Register with RPRA as a producer (unless you import or brand-own products)</li><li>Pay RPRA fees directly (producers pay; SMEs do not typically pay RPRA fees separately)</li><li>Submit waste diversion reports unless above regulatory thresholds</li><li>Achieve specific recycling rate targets as an individual business</li><li>Provide recycling services to employees at no cost (recommended, not required)</li></ul><h2>Simple Waste Station Setup — Step by Step</h2><h3>Step 1: Assess Your Waste Streams</h3><ul><li>Walk through your premises for 15 minutes and note what your business actually generates</li><li>Identify the three or four <strong>highest-volume</strong> waste types (cardboard, food waste, plastic packaging)</li><li>Note any materials currently going to landfill that could be recycled</li></ul><h3>Step 2: Choose the Right Number of Bins</h3><ul><li><strong>At minimum</strong>: Recycling (blue), Organics (green where available), Landfill (grey/black)</li><li>Add specialist bins for high-volume streams: cardboard flat-pack, glass, cooking oil</li><li>Locate bins <strong>where waste is generated</strong> — not just in one central location</li></ul><h3>Step 3: Label Clearly — Use Pictures, Not Just Words</h3><ul><li>Use colour-coded bins matching the collection system in your municipality</li><li>Post a printed guide above each bin with <strong>photos</strong> of accepted and rejected items</li><li>Use <strong>multilingual signage</strong> if your staff speak multiple languages</li></ul><h3>Step 4: Arrange Collection</h3><ul><li>Contact your municipality for blue bin and organics collection eligibility</li><li>Contact a licensed private hauler for recycling and garbage collection</li><li>For specialist materials (cooking oil, cardboard at high volume), contact registered recyclers</li></ul><h3>Step 5: Brief Your Team</h3><ul><li>Hold a 5–10 minute team meeting explaining where each waste type goes and why</li><li>Appoint a <strong>Waste Champion</strong> — one person who checks bins weekly and corrects errors</li><li>Use ongoing toolbox talks to keep awareness fresh</li></ul><h2>Staff Training Basics</h2><p>Staff training does not need to be complicated. The goal is simple: <strong>every team member should know which item goes in which bin, and what to do if they''re unsure.</strong></p><ul><li><strong>Who to train</strong> — All staff including part-time, seasonal, and new employees. Kitchen staff, cleaners, warehouse workers, and office staff all make sorting decisions every day.</li><li><strong>When to train</strong> — During onboarding. Annual refresher. After any change to the waste system.</li><li><strong>How long</strong> — 5–10 minutes is sufficient for the basics.</li><li><strong>What to cover</strong> — Which bin each common waste type goes in; what to do with uncertain items; where to find the waste champion with a question.</li><li><strong>Keep it simple</strong> — One laminated A4 guide posted above each bin is worth more than a 20-minute lecture.</li></ul><h2>Materials with Commercial Value</h2><p>Many materials that SMEs currently <strong>pay to dispose of</strong> have genuine commercial value:</p><ul><li><strong>Cardboard (high volume)</strong> — At sufficient volumes, compacted cardboard can be sold to cardboard recyclers. A <strong>baler pays back in 6–12 months</strong> for many warehouses.</li><li><strong>Aluminum</strong> — Cans, foil, and scrap aluminum are bought by scrap metal dealers at consistently high commodity value.</li><li><strong>Cooking oil</strong> — Collected free (or for a fee) by licensed grease recyclers and converted to biodiesel.</li><li><strong>Stretch wrap / LDPE</strong> — Large clean volumes are accepted by some recyclers. Ask your packaging supplier about take-back.</li><li><strong>Scrap metal</strong> — Steel and mixed metal scrap is bought by scrap dealers. Even small volumes are worth a call.</li><li><strong>Coffee grounds</strong> — Some composters and urban farms accept commercial coffee grounds for free.</li></ul><h2>Hazardous Waste — The Basics</h2><p>All Ontario SMEs that generate hazardous waste have legal obligations to handle, store, and dispose of it correctly. Hazardous waste includes: <strong>batteries, fluorescent bulbs, paints and solvents, motor oil, antifreeze, pesticides, and cleaning chemicals</strong>.</p><ul><li><strong>Never</strong> pour chemicals, oils, or solvents down the drain — this is an offence under the Ontario Water Resources Act</li><li><strong>Never</strong> put batteries or fluorescent bulbs in the general waste</li><li>Contact your municipality for <strong>Household and Small Business Hazardous Waste depot</strong> locations and drop-off days</li><li>For larger quantities, contact a <strong>licensed Ontario hazardous waste contractor</strong></li><li>Use RPRA''s <strong>Where to Recycle map (rpra.ca/where-to-recycle)</strong> to find your nearest registered drop-off</li></ul><h3>One-Change Commitment</h3><p>The most powerful behaviour-change technique in short business training is the "one change" commitment. Identify <strong>one improvement</strong> you can make to your waste setup this week — clearer labels, a new bin location, or a five-minute briefing. That single change compounds across the year.</p>',
   4, 15, true, 70),

  (v_mod_ids[5], v_course_id, 'Final Quiz — SME Recycling in Ontario',
   'A 10-question final assessment covering all four modules. Pass mark 70%.',
   E'<h2>Final Knowledge Check</h2><p>This 10-question quiz covers everything you''ve learned across the four modules of Recycling & Waste Management for SMEs in Ontario. A passing score (70%) demonstrates your readiness to set up correct waste-management practices in your business.</p><p>Questions are drawn from across the course — Ontario''s waste challenge, recycling streams and contamination, EPR rules, and the practical 5-step waste-station setup.</p><p>Good luck!</p>',
   5, 10, true, 70);

  -- Quiz Questions
  -- Module 1
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[1], 'Approximately how much municipal solid waste does Ontario generate per year?', '["2 million tonnes","6 million tonnes","12 million tonnes","25 million tonnes"]'::jsonb, 2, 1),
  (v_mod_ids[1], 'A restaurant manager says: "We just throw everything in one bin — it''s easier." What is the main problem?', '["It is against Ontario building code","Mixing waste increases disposal costs and sends recyclable material to landfill","The bins will overflow more quickly","It is only an issue for large businesses"]'::jsonb, 1, 2),
  (v_mod_ids[1], 'Which of the following correctly describes Ontario''s IC&I sector''s share of total provincial waste?', '["About 10%","About 20%","About 40%","About 70%"]'::jsonb, 2, 3);

  -- Module 2
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[2], 'A café staff member puts leftover soup and used paper cups in the blue recycling bin. What is the most likely outcome?', '["The soup will be separated at the sorting facility","The materials will be contaminated and may be sent to landfill","The paper cups will be recycled and the soup composted","There is no problem — organics are allowed in recycling bins"]'::jsonb, 1, 1),
  (v_mod_ids[2], 'Which of the following items is ALWAYS accepted in Ontario''s blue recycling bin?', '["A rinsed #2 HDPE shampoo bottle","A plastic bag containing clean recyclables","A Styrofoam takeout container","A used paper tissue"]'::jsonb, 0, 2),
  (v_mod_ids[2], 'Which waste stream should a restaurant use for raw meat scraps, vegetable peelings, and eggshells?', '["Blue recycling bin","Black garbage bin","Green organics bin","Special hazardous waste collection"]'::jsonb, 2, 3);

  -- Module 3
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[3], 'Under Ontario''s Extended Producer Responsibility system, who is primarily responsible for funding Blue Box recycling?', '["Ontario municipalities","Taxpayers through property taxes","Producers — businesses that manufacture or import products and packaging","Ontario SMEs directly"]'::jsonb, 2, 1),
  (v_mod_ids[3], 'What does RPRA stand for and what does it do?', '["Regional Planning and Recycling Authority — manages municipal garbage collection","Resource Productivity and Recovery Authority — enforces Ontario''s recycling programs and sets targets for producers","Recycling Producers and Retailers Association — a voluntary business group","Regional Procurement and Recycling Agency — buys recycled materials from businesses"]'::jsonb, 1, 2),
  (v_mod_ids[3], 'Which of the following best describes the role of an Ontario SME (that is NOT a registered producer) under EPR?', '["SMEs have no role — EPR is entirely a producer issue","SMEs influence EPR outcomes through correct sorting, purchasing decisions, and staff behaviour","SMEs must register with RPRA and pay annual program fees","SMEs are required to achieve specific recycling rate targets"]'::jsonb, 1, 3);

  -- Module 4
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[4], 'A retail store manager wants to improve waste management. What is the most cost-effective first step?', '["Purchase a commercial compactor immediately","Conduct a 15-minute waste walkthrough, set up labelled bins, and brief staff","Hire a sustainability consultant for a full waste audit","Wait until the municipality introduces new requirements"]'::jsonb, 1, 1),
  (v_mod_ids[4], 'A coffee shop generates 20 litres of used cooking oil per week. What should the owner do?', '["Pour it down the drain after diluting with water","Mix it with food waste in the organics bin","Contact a licensed grease recycler — many collect cooking oil for free or at profit","Place it in sealed containers in the general garbage"]'::jsonb, 2, 2),
  (v_mod_ids[4], 'Which of the following is the single most effective tool for reducing staff recycling mistakes in an SME?', '["Weekly staff recycling quizzes","A 30-minute mandatory training video","Clear, picture-based labels above every bin showing accepted and rejected items","Fines for incorrect sorting"]'::jsonb, 2, 3);

  -- Final Quiz (Module 5) — 10 questions
  INSERT INTO public.quiz_questions (module_id, question, options, correct_answer_index, order_index) VALUES
  (v_mod_ids[5], 'What percentage of Ontario''s total waste is currently diverted from landfill?', '["About 10%","About 33%","About 60%","About 80%"]'::jsonb, 1, 1),
  (v_mod_ids[5], 'A restaurant places a plastic bag full of clean recycling in the blue bin. What happens at the sorting facility?', '["The bag is opened and the contents sorted correctly","The whole bag is treated as garbage and sent to landfill","The bag is composted","Nothing — plastic bags are accepted in most Ontario blue bins"]'::jsonb, 1, 2),
  (v_mod_ids[5], 'Which of the following items should NEVER go in the blue recycling bin?', '["A rinsed peanut butter jar","Flattened cardboard boxes","Batteries of any type","A rinsed glass pasta sauce jar"]'::jsonb, 2, 3),
  (v_mod_ids[5], 'Under Ontario''s EPR framework effective January 2026, who pays for the Blue Box recycling program?', '["Ontario property taxpayers","Municipal governments","Producers — businesses that manufacture or import products and packaging into Ontario","The federal government''s environmental fund"]'::jsonb, 2, 4),
  (v_mod_ids[5], 'A small office generates significant paper waste. The best practice for managing shredded confidential paper is:', '["Place it loose in the recycling bin","Place it in a sealed paper bag and put the bag in the recycling bin","Always send it to a secure document destruction company — it cannot be recycled","Mix it with food waste for composting"]'::jsonb, 1, 5),
  (v_mod_ids[5], 'An Ontario SME imports branded merchandise directly from overseas. Under RPRA''s EPR rules, this SME:', '["Is entirely exempt as an SME","Must pay a voluntary eco-fee at point of import","May be classified as a producer with obligations under RPRA programs","Is covered by the foreign manufacturer''s Canadian registration"]'::jsonb, 2, 6),
  (v_mod_ids[5], 'What is the most practical first step for an SME setting up a waste management system?', '["Hire an environmental consultant for a full audit","Walk through the premises, identify the top 3–4 waste streams, and set up labelled bins accordingly","Contact RPRA to register as a producer","Wait for the municipality to provide bins and guidance"]'::jsonb, 1, 7),
  (v_mod_ids[5], 'A café owner notices staff often put food scraps in the recycling bin instead of the organics bin. What is the most effective solution?', '["Remove the organics bin to eliminate confusion","Send all staff for formal waste management certification","Move the organics bin next to the food preparation area and add a clear picture label","Accept the situation — some contamination is unavoidable"]'::jsonb, 2, 8),
  (v_mod_ids[5], 'Which of the following materials commonly generated by SMEs has commercial resale value?', '["Food-soiled cardboard","Used fluorescent bulbs","High-volume clean corrugated cardboard","Stretch wrap mixed with tape and labels"]'::jsonb, 2, 9),
  (v_mod_ids[5], 'A hardware store finds several boxes of old motor oil and pesticides from a previous owner. The correct action is to:', '["Dilute the materials and dispose of them down the industrial drain","Mix them with general garbage in sealed containers","Contact a licensed hazardous waste contractor or the municipal HHW depot for proper disposal","Donate them to other businesses who might use them"]'::jsonb, 2, 10);

END $$;
